1	package server
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"fmt"
7		"sort"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// ChunkSize is the fixed split size for object bodies. All chunks except the
14	// final one have exactly this many bytes.
15	const ChunkSize = 1048576
16	
17	// MaxObjectSize is the largest accepted object body in bytes.
18	const MaxObjectSize = 67108864
19	
20	// cidPrefix prefixes every content identifier.
21	const cidPrefix = "sha256:"
22	
23	// object is a fully received object held in process memory.
24	type object struct {
25		cid    string
26		size   int
27		chunks [][]byte // raw chunk bytes, in reconstruction order
28		cids   []string // chunk identifiers, parallel to chunks
29	}
30	
31	// pin records a retention guarantee for one object. A nil expiresAt means
32	// the object is retained permanently; otherwise the pin is in force until
33	// the given instant. Pins live in process memory only and are not preserved
34	// across restarts.
35	type pin struct {
36		expiresAt *time.Time
37	}
38	
39	// validPin reports whether p is in force at now. Expired pins are
40	// equivalent to no pin at all.
41	func validPin(p pin, now time.Time) bool {
42		return p.expiresAt == nil || p.expiresAt.After(now)
43	}
44	
45	// recursivePin records a retention guarantee for a directory root and every
46	// object reachable from it at commit time. members holds the unique member
47	// cids, root included, sorted lexically; it is the commit-time snapshot
48	// returned by reads and the retention set used by garbage collection. bytes
49	// is the sum of the member body sizes. A nil expiresAt means the record is
50	// in force permanently. Records live in process memory only, are not listed
51	// by GET /v1/pins and append no audit events.
52	type recursivePin struct {
53		expiresAt *time.Time
54		members   []string
55		bytes     int
56	}
57	
58	// validRecursivePin reports whether rp is in force at now. Expired records
59	// are equivalent to no record at all.
60	func validRecursivePin(rp recursivePin, now time.Time) bool {
61		return rp.expiresAt == nil || rp.expiresAt.After(now)
62	}
63	
64	// blockRef holds one unique stored block. refs counts the live objects that
65	// reference the block; a block repeated within one object still counts once.
66	type blockRef struct {
67		data []byte
68		refs int
69	}
70	
71	// store is an in-process content-addressed object store. Objects are
72	// immutable once inserted; inserts and deletes happen under the write lock
73	// so readers never observe a partially written object. Blocks are stored
74	// once and shared by every object that references them; a block is dropped
75	// as soon as no live object references it.
76	type store struct {
77		mu            sync.RWMutex
78		objects       map[string]*object
79		blocks        map[string]*blockRef
80		pins          map[string]pin
81		recursivePins map[string]recursivePin
82		metadata      map[string][]metadataRevision
83		refs          map[string][]refRevision
84		audit         *auditLog // nil until wired by the HTTP surface
85	}
86	
87	func newStore() *store {
88		return &store{
89			objects:       make(map[string]*object),
90			blocks:        make(map[string]*blockRef),
91			pins:          make(map[string]pin),
92			recursivePins: make(map[string]recursivePin),
93			metadata:      make(map[string][]metadataRevision),
94			refs:          make(map[string][]refRevision),
95		}
96	}
97	
98	// chunkCID returns the identifier for one chunk's raw bytes.
99	func chunkCID(data []byte) string {
100		sum := sha256.Sum256(data)
101		return cidPrefix + hex.EncodeToString(sum[:])
102	}
103	
104	// rootCID derives the object identifier from the deterministic manifest: the
105	// total object length followed by the ordered chunk identifiers, encoded as
106	// "size:<N>\n" then one "<cid>\n" line per chunk.
107	func rootCID(size int, cids []string) string {
108		var b strings.Builder
109		fmt.Fprintf(&b, "size:%d\n", size)
110		for _, c := range cids {
111			b.WriteString(c)
112			b.WriteByte('\n')
113		}
114		sum := sha256.Sum256([]byte(b.String()))
115		return cidPrefix + hex.EncodeToString(sum[:])
116	}
117	
118	// put stores the object, or returns the existing one when the same root
119	// identifier is already present. Exactly one concurrent caller observes
120	// created == true for a given object. Newly stored objects register their
121	// unique chunks in the shared block table; repeated chunks within the
122	// object and chunks shared with other objects are stored only once. The
123	// audit event for the action is appended under the same lock, so event
124	// order matches commit order; providerID is set only for remote fetches.
125	func (s *store) put(obj *object, action string, providerID *string) (stored *object, created bool) {
126		s.mu.Lock()
127		defer s.mu.Unlock()
128		if existing, ok := s.objects[obj.cid]; ok {
129			s.audit.append(objectAuditRecord(action, existing, false, providerID))
130			return existing, false
131		}
132		s.objects[obj.cid] = obj
133		seen := make(map[string]bool, len(obj.cids))
134		for i, c := range obj.cids {
135			if b, ok := s.blocks[c]; ok {
136				obj.chunks[i] = b.data // share the stored copy
137				if !seen[c] {
138					b.refs++
139				}
140			} else {
141				s.blocks[c] = &blockRef{data: obj.chunks[i], refs: 1}
142			}
143			seen[c] = true
144		}
145		s.audit.append(objectAuditRecord(action, obj, true, providerID))
146		return obj, true
147	}
148	
149	// get returns the object for a root identifier, or nil when absent.
150	func (s *store) get(cid string) *object {
151		s.mu.RLock()
152		defer s.mu.RUnlock()
153		return s.objects[cid]
154	}
155	
156	// getBlock returns the raw bytes of a stored block, or nil when no live
157	// object references it.
158	func (s *store) getBlock(cid string) []byte {
159		s.mu.RLock()
160		defer s.mu.RUnlock()
161		if b, ok := s.blocks[cid]; ok {
162			return b.data
163		}
164		return nil
165	}
166	
167	// storageStats is a consistent snapshot of the store's occupancy.
168	type storageStats struct {
169		objects      int
170		logicalBytes int
171		blocks       int
172		storedBytes  int
173	}
174	
175	// stats snapshots object and deduplicated block occupancy under one lock
176	// hold, so the four counters always describe the same instant.
177	func (s *store) stats() storageStats {
178		s.mu.RLock()
179		defer s.mu.RUnlock()
180		st := storageStats{objects: len(s.objects), blocks: len(s.blocks)}
181		for _, obj := range s.objects {
182			st.logicalBytes += obj.size
183		}
184		for _, b := range s.blocks {
185			st.storedBytes += len(b.data)
186		}
187		return st
188	}
189	
190	// setPin pins cid with the given expiration, replacing any previous pin. It
191	// reports ok == false when the object does not exist. created is true when
192	// no valid pin was in force at now. The check and the update are atomic
193	// with respect to garbage collection.
194	func (s *store) setPin(cid string, expiresAt *time.Time, now time.Time) (created, ok bool) {
195		s.mu.Lock()
196		defer s.mu.Unlock()
197		if _, exists := s.objects[cid]; !exists {
198			return false, false
199		}
200		existing, found := s.pins[cid]
201		created = !found || !validPin(existing, now)
202		s.pins[cid] = pin{expiresAt: expiresAt}
203		result := "updated"
204		if created {
205			result = "created"
206		}
207		s.audit.append(auditRecord{action: auditPinPut, result: result, cid: strPtr(cid)})
208		return created, true
209	}
210	
211	// removePin deletes the pin for cid, reporting whether a valid pin was in
212	// force at now. Expired pins are removed lazily and reported as absent.
213	func (s *store) removePin(cid string, now time.Time) bool {
214		s.mu.Lock()
215		defer s.mu.Unlock()
216		p, found := s.pins[cid]
217		if !found || !validPin(p, now) {
218			delete(s.pins, cid)
219			return false
220		}
221		delete(s.pins, cid)
222		s.audit.append(auditRecord{action: auditPinDelete, result: "deleted", cid: strPtr(cid)})
223		return true
224	}
225	
226	// pinEntry is one live pin in a listing.
227	type pinEntry struct {
228		cid       string
229		expiresAt *time.Time
230	}
231	
232	// listPins returns the pins in force at now, sorted by cid.
233	func (s *store) listPins(now time.Time) []pinEntry {
234		s.mu.RLock()
235		defer s.mu.RUnlock()
236		entries := []pinEntry{}
237		for cid, p := range s.pins {
238			if validPin(p, now) {
239				entries = append(entries, pinEntry{cid: cid, expiresAt: p.expiresAt})
240			}
241		}
242		sort.Slice(entries, func(i, j int) bool { return entries[i].cid < entries[j].cid })
243		return entries
244	}
245	
246	// recursivePinChild is one pending directory entry in a traversal.
247	type recursivePinChild struct {
248		entry directoryEntry
249		depth int // depth of the referenced object; the root is depth 0
250	}
251	
252	// setRecursivePin validates and traverses the directory tree rooted at cid
253	// and atomically commits the recursive pin record, replacing any previous
254	// record. The whole traversal, every existence check and the commit run
255	// under one write-lock hold, so they observe a single instant and are atomic
256	// with respect to garbage collection: a commit that lands first protects
257	// every member, and a sweep that lands first makes the traversal fail. A
258	// failure stores nothing. created is true when no valid record was in force
259	// at now. The returned string is empty on success or the error code to
260	// report: object_not_found, invalid_directory, recursive_pin_target_missing
261	// or recursive_pin_too_large.
262	func (s *store) setRecursivePin(cid string, expiresAt *time.Time, now time.Time) (rp recursivePin, created bool, code string) {
263		s.mu.Lock()
264		defer s.mu.Unlock()
265		root, ok := s.objects[cid]
266		if !ok {
267			return recursivePin{}, false, "object_not_found"
268		}
269		rootEntries, valid := parseDirectory(root.body())
270		if !valid {
271			return recursivePin{}, false, "invalid_directory"
272		}
273		members := []string{cid}
274		seen := map[string]bool{cid: true}
275		totalBytes := root.size
276		var stack []recursivePinChild
277		// pushChildren queues entries in deterministic traversal order: children
278		// are visited by ascending entry name (byte order matches code-point
279		// order for valid UTF-8), so error precedence does not depend on map
280		// iteration order.
281		pushChildren := func(entries map[string]directoryEntry, depth int) {
282			sorted := make([]directoryEntry, 0, len(entries))
283			for _, e := range entries {
284				sorted = append(sorted, e)
285			}
286			sort.Slice(sorted, func(i, j int) bool { return sorted[i].name < sorted[j].name })
287			for i := len(sorted) - 1; i >= 0; i-- {
288				stack = append(stack, recursivePinChild{entry: sorted[i], depth: depth})
289			}
290		}
291		pushChildren(rootEntries, 1)
292		for len(stack) > 0 {
293			c := stack[len(stack)-1]
294			stack = stack[:len(stack)-1]
295			if seen[c.entry.cid] {
296				// Already a member: shared subtrees and cycles count once.
297				continue
298			}
299			if c.depth > maxRecursivePinDepth {
300				return recursivePin{}, false, "recursive_pin_too_large"
301			}
302			obj := s.objects[c.entry.cid]
303			if obj == nil {
304				return recursivePin{}, false, "recursive_pin_target_missing"
305			}
306			seen[c.entry.cid] = true
307			members = append(members, c.entry.cid)
308			if len(members) > maxRecursivePinMembers {
309				return recursivePin{}, false, "recursive_pin_too_large"
310			}
311			totalBytes += obj.size
312			if c.entry.typ == "directory" {
313				entries, valid := parseDirectory(obj.body())
314				if !valid {
315					return recursivePin{}, false, "invalid_directory"
316				}
317				pushChildren(entries, c.depth+1)
318			}
319		}
320		sort.Strings(members)
321		existing, found := s.recursivePins[cid]
322		created = !found || !validRecursivePin(existing, now)
323		rp = recursivePin{expiresAt: expiresAt, members: members, bytes: totalBytes}
324		s.recursivePins[cid] = rp
325		return rp, created, ""
326	}
327	
328	// recursivePinAt returns the record in force at now for cid, or false when
329	// none exists or the record has expired.
330	func (s *store) recursivePinAt(cid string, now time.Time) (recursivePin, bool) {
331		s.mu.RLock()
332		defer s.mu.RUnlock()
333		rp, found := s.recursivePins[cid]
334		if !found || !validRecursivePin(rp, now) {
335			return recursivePin{}, false
336		}
337		return rp, true
338	}
339	
340	// removeRecursivePin deletes the record for cid, reporting whether a valid
341	// record was in force at now. Expired records are removed lazily and
342	// reported as absent. Deletion never removes the member objects and appends
343	// no audit event.
344	func (s *store) removeRecursivePin(cid string, now time.Time) bool {
345		s.mu.Lock()
346		defer s.mu.Unlock()
347		rp, found := s.recursivePins[cid]
348		if !found || !validRecursivePin(rp, now) {
349			delete(s.recursivePins, cid)
350			return false
351		}
352		delete(s.recursivePins, cid)
353		return true
354	}
355	
356	// collectGarbage removes every object retained neither by a valid direct
357	// pin nor by a valid recursive pin record at now, or only counts them when
358	// dryRun is true. It returns the affected cids in lexical order and the sum
359	// of their body sizes. The sweep is atomic with respect to pin updates and
360	// object reads.
361	func (s *store) collectGarbage(now time.Time, dryRun bool) (cids []string, totalBytes int) {
362		s.mu.Lock()
363		defer s.mu.Unlock()
364		protected := make(map[string]bool)
365		for _, rp := range s.recursivePins {
366			if !validRecursivePin(rp, now) {
367				continue
368			}
369			for _, member := range rp.members {
370				protected[member] = true
371			}
372		}
373		cids = []string{}
374		for cid, obj := range s.objects {
375			if p, pinned := s.pins[cid]; pinned && validPin(p, now) {
376				continue
377			}
378			if protected[cid] {
379				continue
380			}
381			cids = append(cids, cid)
382			totalBytes += obj.size
383		}
384		sort.Strings(cids)
385		if !dryRun {
386			for _, cid := range cids {
387				obj := s.objects[cid]
388				delete(s.objects, cid)
389				delete(s.metadata, cid)
390				s.releaseBlocks(obj)
391			}
392			for cid, p := range s.pins {
393				if !validPin(p, now) {
394					delete(s.pins, cid)
395				}
396			}
397			for cid, rp := range s.recursivePins {
398				if !validRecursivePin(rp, now) {
399					delete(s.recursivePins, cid)
400				}
401			}
402		}
403		action := auditGCCollect
404		result := "collected"
405		if dryRun {
406			action = auditGCPreview
407			result = "previewed"
408		}
409		s.audit.append(auditRecord{
410			action:  action,
411			result:  result,
412			objects: intPtr(len(cids)),
413			bytes:   intPtr(totalBytes),
414		})
415		return cids, totalBytes
416	}
417	
418	// releaseBlocks drops the object's block references, removing any block no
419	// other live object uses. The caller must hold the write lock.
420	func (s *store) releaseBlocks(obj *object) {
421		seen := make(map[string]bool, len(obj.cids))
422		for _, c := range obj.cids {
423			if seen[c] {
424				continue
425			}
426			seen[c] = true
427			b, ok := s.blocks[c]
428			if !ok {
429				continue
430			}
431			b.refs--
432			if b.refs == 0 {
433				delete(s.blocks, c)
434			}
435		}
436	}
437	
438	// metadataRevision is one immutable metadata revision of an object. Each
439	// object's revisions are kept in commit order, so the revision number of
440	// entry i is i+1. Metadata lives in process memory only: it creates no pin,
441	// takes no part in storage statistics, bundles or the audit log, and is
442	// deleted atomically with its object by garbage collection.
443	type metadataRevision struct {
444		revision    int64
445		contentType *string
446		labels      map[string]string
447		updatedAt   time.Time
448	}
449	
450	// commitMetadata appends one metadata revision for cid when expected equals
451	// the current revision number (0 before the first write). The check and the
452	// append happen under the write lock, so exactly one of several concurrent
453	// writers carrying the same expected revision commits. The returned string
454	// is empty on success or the error code to report: object_not_found or
455	// revision_conflict. created is true for the first revision of an object.
456	func (s *store) commitMetadata(cid string, expected int64, contentType *string, labels map[string]string, now time.Time) (rev metadataRevision, created bool, code string) {
457		s.mu.Lock()
458		defer s.mu.Unlock()
459		if _, ok := s.objects[cid]; !ok {
460			return metadataRevision{}, false, "object_not_found"
461		}
462		history := s.metadata[cid]
463		if int64(len(history)) != expected {
464			return metadataRevision{}, false, "revision_conflict"
465		}
466		rev = metadataRevision{
467			revision:    expected + 1,
468			contentType: contentType,
469			labels:      labels,
470			updatedAt:   now.UTC(),
471		}
472		s.metadata[cid] = append(history, rev)
473		return rev, expected == 0, ""
474	}
475	
476	// metadataAt returns the current metadata revision for cid, or the requested
477	// historical revision when revision > 0. The returned string is empty on
478	// success or the error code to report: object_not_found, metadata_not_found
479	// or metadata_revision_not_found.
480	func (s *store) metadataAt(cid string, revision int64) (metadataRevision, string) {
481		s.mu.RLock()
482		defer s.mu.RUnlock()
483		if _, ok := s.objects[cid]; !ok {
484			return metadataRevision{}, "object_not_found"
485		}
486		history := s.metadata[cid]
487		if len(history) == 0 {
488			return metadataRevision{}, "metadata_not_found"
489		}
490		if revision == 0 {
491			return history[len(history)-1], ""
492		}
493		if revision > int64(len(history)) {
494			return metadataRevision{}, "metadata_revision_not_found"
495		}
496		return history[revision-1], ""
497	}
498	
499	// refRevision is one immutable revision of a named reference. A ref points
500	// at an object by cid but creates no pin: the target may be garbage
501	// collected while the ref history stays readable. Revisions live in
502	// process memory only, take no part in storage statistics, bundles or the
503	// audit log, and are not deleted when the target object is collected.
504	type refRevision struct {
505		revision  int64
506		cid       string
507		updatedAt time.Time
508	}
509	
510	// commitRef appends one revision for name when expected equals the current
511	// revision number (0 before the first write) and cid names a live object.
512	// The existence check, revision check and append happen under one write
513	// lock, so exactly one of several concurrent writers carrying the same
514	// expected revision commits. The returned string is empty on success or the
515	// error code to report: object_not_found or revision_conflict. created is
516	// true for the first revision of a name. A new revision is recorded even
517	// when the cid is unchanged.
518	func (s *store) commitRef(name, cid string, expected int64, now time.Time) (rev refRevision, created bool, code string) {
519		s.mu.Lock()
520		defer s.mu.Unlock()
521		if _, ok := s.objects[cid]; !ok {
522			return refRevision{}, false, "object_not_found"
523		}
524		history := s.refs[name]
525		if int64(len(history)) != expected {
526			return refRevision{}, false, "revision_conflict"
527		}
528		rev = refRevision{revision: expected + 1, cid: cid, updatedAt: now.UTC()}
529		s.refs[name] = append(history, rev)
530		return rev, expected == 0, ""
531	}
532	
533	// refAt returns the current ref revision for name, or the requested
534	// historical revision when revision > 0. The returned string is empty on
535	// success or the error code to report: ref_not_found or
536	// ref_revision_not_found. Ref metadata stays readable after the target
537	// object has been garbage collected.
538	func (s *store) refAt(name string, revision int64) (refRevision, string) {
539		s.mu.RLock()
540		defer s.mu.RUnlock()
541		history := s.refs[name]
542		if len(history) == 0 {
543			return refRevision{}, "ref_not_found"
544		}
545		if revision == 0 {
546			return history[len(history)-1], ""
547		}
548		if revision > int64(len(history)) {
549			return refRevision{}, "ref_revision_not_found"
550		}
551		return history[revision-1], ""
552	}
553	
554	// resolveRefObject resolves a ref revision and its target object against a
555	// single consistent snapshot of the store: the read lock is held across
556	// both the history lookup and the object lookup, so resolution and object
557	// reading observe the same instant. It returns the resolved revision (also
558	// when the object is gone) and the error code to report: ref_not_found,
559	// ref_revision_not_found or reference_target_missing.
560	func (s *store) resolveRefObject(name string, revision int64) (rev refRevision, obj *object, code string) {
561		s.mu.RLock()
562		defer s.mu.RUnlock()
563		history := s.refs[name]
564		if len(history) == 0 {
565			return refRevision{}, nil, "ref_not_found"
566		}
567		if revision != 0 && revision > int64(len(history)) {
568			return refRevision{}, nil, "ref_revision_not_found"
569		}
570		if revision == 0 {
571			rev = history[len(history)-1]
572		} else {
573			rev = history[revision-1]
574		}
575		obj = s.objects[rev.cid]
576		if obj == nil {
577			return rev, nil, "reference_target_missing"
578		}
579		return rev, obj, ""
580	}
581	
582	// validCID reports whether s has the "sha256:<64 lowercase hex>" shape.
583	func validCID(s string) bool {
584		if len(s) != len(cidPrefix)+64 || !strings.HasPrefix(s, cidPrefix) {
585			return false
586		}
587		for _, c := range s[len(cidPrefix):] {
588			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
589				return false
590			}
591		}
592		return true
593	}
