1	package server
2	
3	import (
4		"crypto/aes"
5		"crypto/cipher"
6		"crypto/rand"
7		"crypto/sha256"
8		"encoding/base64"
9		"encoding/hex"
10		"encoding/json"
11		"fmt"
12		"io"
13		"mime"
14		"net/http"
15		"strconv"
16		"sync"
17	)
18	
19	// sealedAlgorithm is the only seal algorithm accepted by the vault.
20	const sealedAlgorithm = "AES-256-GCM"
21	
22	// sealedKeyHeader carries the caller-held Base64 key.
23	const sealedKeyHeader = "X-CidVault-Key"
24	
25	// sealedNonceSize is the per-object GCM nonce length.
26	const sealedNonceSize = 12
27	
28	// sealedKeySize is the required key length in bytes.
29	const sealedKeySize = 32
30	
31	// sealedObject is one encrypted envelope held in process memory. Only the
32	// nonce and the ciphertext (including its GCM authentication tag) are
33	// retained; neither the plaintext nor the key outlives a request.
34	type sealedObject struct {
35		size       int
36		nonce      []byte
37		ciphertext []byte // ciphertext with the GCM tag appended
38	}
39	
40	// sealedStore is an in-process envelope store, deliberately separate from
41	// the plaintext object store: sealed objects take no part in the object
42	// lifecycle, blocks, pins, garbage collection, storage statistics or the
43	// audit log. Inserts and deletes happen under the write lock so a reader
44	// observes either the complete envelope or its absence.
45	type sealedStore struct {
46		mu      sync.RWMutex
47		objects map[string]*sealedObject
48	}
49	
50	func newSealedStore() *sealedStore {
51		return &sealedStore{objects: make(map[string]*sealedObject)}
52	}
53	
54	// sealedAAD builds the authenticated data bound to one object: the domain
55	// line followed by the plaintext length.
56	func sealedAAD(size int) []byte {
57		return []byte(fmt.Sprintf("cidvault-sealed-v1\nsize:%d\n", size))
58	}
59	
60	// sealedCID derives the content identifier over the associated data, the
61	// nonce and the ciphertext (authentication tag included).
62	func sealedCID(aad, nonce, ciphertext []byte) string {
63		h := sha256.New()
64		h.Write(aad)
65		h.Write(nonce)
66		h.Write(ciphertext)
67		sum := h.Sum(nil)
68		return cidPrefix + hex.EncodeToString(sum)
69	}
70	
