		if i > 0 && t <= prev {
			return false
		}
		prev = t
		u, err := url.Parse(t)
		if err != nil {
			return false
		}
		if u.Scheme != "http" && u.Scheme != "https" {
			return false
		}
		if u.Hostname() == "" || u.User != nil {
			return false
		}
